import{z as B,x as A,o as r,c as g,q as n,j as l,D as e,d as i,s,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const y=JSON.parse('{"title":"Bewley–Huggett–Aiyagari","description":"","frontmatter":{"title":"Bewley–Huggett–Aiyagari","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bewley-aiyagari.md","filePath":"econ/bewley-aiyagari.md","lastUpdated":1791413859000}'),d={name:"econ/bewley-aiyagari.md"};function p(m,a,u,C,h,c){const E=A("Mermaid");return r(),g("div",null,[a[2]||(a[2]=n('<h1 id="bewley–huggett–aiyagari" tabindex="-1">Bewley–Huggett–Aiyagari <a class="header-anchor" href="#bewley–huggett–aiyagari" aria-label="Permalink to &quot;Bewley–Huggett–Aiyagari&quot;">​</a></h1><div class="epigraph"><p>劳动收入不可完全保险时，家庭用无风险资产自保；均衡利率使资产需求等于外生供给（或资本）。</p><footer>—— Bewley；Huggett, The Risk-Free Rate in Heterogeneous-Agent Incomplete-Insurance Economies, JEDC 1993；Aiyagari, Uninsured Idiosyncratic Risk and Aggregate Saving, QJE 1994</footer></div><p><a href="/econ/narrative-hf-identification">上一课</a>把加总冲击识别到能画 IRF 为止。IRF 背后仍是代表性欧拉。本课缺口是<strong>关掉完全保险</strong>：特异收入风险 + 借贷约束 ⇒ 财富分布成为均衡对象。不重做 SVAR，不把 Krusell–Smith 的总量冲击提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代表性 Ramsey 的 \\(\\beta(1+r)=1\\) 钉死稳态利率。Huggett：只有债券、净供给为零或外生，异质禀赋与约束下，预防性需求把 \\(r\\) 压到时间偏好之下。Aiyagari：资产是生产性资本，特异风险提高总储蓄，稳态 \\(K\\) 高于完全保险经济。Bewley 传统提供装置。缺口不是再讲预防性储蓄的 \\(u&#39;&#39;&#39;\\)，而是：不完全市场一般均衡把分布 \\(\\mu(a,z)\\) 与价格一起解。</p><p><span class="marginnote">术语翻译：「不完全保险」指劳动收入的风险没有对应市场可买——你买不到一份「保自己永不失业」的完全合同；家庭只能靠持有无风险资产自己给自己保险，这就是「自保」（self-insurance）。</span></p><p><span class="marginnote">Huggett, <em>JEDC</em> 1993。Aiyagari, <em>QJE</em> 109(3), 1994, 659–684。Imrohoroglu 同期有失业自保。本课是稳态，总量确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>个人状态 \\((a,z)\\)，\\(z\\) 为收入马尔可夫。政策 \\(a&#39;=g(a,z;r)\\) 由贝尔曼（本课程第一课的算子）加 \\(a&#39;\\ge\\underline a\\)。不变分布 \\(\\mu\\) 满足 \\(\\mu=T_g\\mu\\)。出清：\\(\\int a&#39;\\,d\\mu=A\\)（债券）或 \\(=\\int k\\,d\\mu\\)（资本）。算法：猜 \\(r\\)，解家庭，更新总量，直到出清。这是 VFI 加分布迭代，不是新理论。</p><p><span class="marginnote">数字实例：从 \\(r=3\\%\\) 猜起，解出家庭后人均资产需求是年收入的 1.4 倍，而市场只供给 1.1 倍——资产太抢手，说明 \\(r\\) 偏高；换 \\(r=2.5\\%\\) 重来，直到需求与供给两个数对上为止。</span></p>',10)),(r(),l(o,null,{default:e(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%8C%9C%20r%22%5D%20--%3E%20HH%5B%22%E8%A7%A3%E5%AE%B6%E5%BA%AD%20g%22%5D%0A%20%20HH%20--%3E%20MU%5B%22%E4%B8%8D%E5%8F%98%E5%88%86%E5%B8%83%20%CE%BC%22%5D%0A%20%20MU%20--%3E%20MKT%5B%22%E8%B5%84%E4%BA%A7%E5%87%BA%E6%B8%85%22%5D%0A%20%20MKT%20--%3E%20R%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"加总消费仍较平滑：特异风险在截面抵消。总量矩可以看起来像代表性模型，微观 MPC 与财富基尼不行——后课逐条拆。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是自保需求抬高资产价格（压低 \\(r\\)）或抬高 \\(K\\)。约束附近的人欧拉变不等式，MPC 高；富人接近完全市场欧拉，MPC 低。加总欧拉不是某个 \\(u'(C)\\)，而是财富加权的一阶条件混合。代表性 DSGE 的贝叶斯估计吃不到这个混合，除非显式异质。",-1)),(r(),l(o,null,{default:e(()=>[s(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20INC%5B%22%E6%94%B6%E5%85%A5%E5%86%B2%E5%87%BB%20z%20%E5%BF%BD%E9%AB%98%E5%BF%BD%E4%BD%8E%22%5D%20--%3E%20NOR%5B%22%E6%B2%A1%E6%9C%89%E4%BF%9D%E9%99%A9%E5%B8%82%E5%9C%BA%E5%8F%AF%E5%AF%B9%E5%86%B2%22%5D%0A%20%20NOR%20--%3E%20BUF%5B%22%E6%8C%81%E6%9C%89%E7%BC%93%E5%86%B2%E8%B5%84%E4%BA%A7%20a%20%E8%87%AA%E4%BF%9D%22%5D%0A%20%20CON%5B%22%E7%BA%A6%E6%9D%9F%20a%20%E4%B8%8D%E8%AE%B8%E4%BD%8E%E4%BA%8E%E4%B8%8B%E9%99%90%22%5D%20--%3E%20MPC%5B%22%E7%BA%A6%E6%9D%9F%E9%99%84%E8%BF%91%EF%BC%9AMPC%20%E5%BE%88%E9%AB%98%22%5D%0A%20%20BUF%20--%3E%20RICH%5B%22%E8%B5%84%E4%BA%A7%E5%85%85%E8%B6%B3%E5%90%8E%E6%8E%A5%E8%BF%91%E5%AE%8C%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%0A%20%20RICH%20--%3E%20MPCL%5B%22%E5%AF%8C%E4%BA%BA%EF%BC%9AMPC%20%E5%BE%88%E4%BD%8E%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>没有总量冲击时，宏观时间序列是平的。周期要靠外生总量 \\(Z_t\\)——下一课 Krusell–Smith：分布成为总量状态。</p><p><span class="marginnote">稳态财富分布往往比数据更薄的右尾，因为收入过程不够持久、没有收益异质或创业。帕累托尾是再后课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无总量风险、无名义刚性、无政府。HANK 把 NK 价格粘性接进来，不是本课。也不估计收入过程的全部计量（Guvenen、Kaplan 等后用）。劳动供给内生、离散选择、耐久品，都是同一装置的扩充。</p><p><span class="marginnote">常见误区：以为加总消费平滑就证明代表性家庭成立。特异风险在截面上确实互相抵消，但 MPC 的分布、财富基尼、家庭对一笔刺激支出的反应，代表性模型全都给不出——总量矩像，微观矩不像。</span></p><p>后课默认：不完全市场稳态 = 家庭贝尔曼 + 不变分布 + 资产出清；\\(r\\lt \\rho\\) 可来自预防性。下一课：加上总量冲击，分布如何被「近似」成有限状态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Huggett/Aiyagari：不可保风险 + 约束 ⇒ 分布与 \\(r\\)（或 \\(K\\)）联立。</li><li>加总可平滑，微观 MPC 已异质。</li><li>稳态、无总量冲击。</li><li>出处：Huggett, <em>JEDC</em> 1993；Aiyagari, <em>QJE</em> 1994。</li></ul>',8))])}const f=B(d,[["render",p]]);export{y as __pageData,f as default};
